R_API void r_egg_printf(REgg *egg, const char *fmt, ...) { /* <=== r_egg_printf */ 
	va_list ap;
	int len;
	char buf[1024];
	va_start (ap, fmt);
	len = vsnprintf (buf, sizeof (buf), fmt, ap);
	r_buf_append_bytes (egg->buf, (const ut8 *)buf, len);
	va_end (ap);
}

static void rcc_reset_callname(REgg *egg) { /* <=== rcc_reset_callname */ 
	R_FREE (egg->lang.callname);
	egg->lang.nargs = 0;
}

static inline int is_space(char c) { /* <=== is_space */ 
	return c == ' ' || c == '\t' || c == '\n' || c == '\r';
}

static void set_nested(REgg *egg, const char *s) { /* <=== set_nested */ 
	int i = 0;
	if (CTX < 1) {
		return;
	}
	free (egg->lang.nested[CTX]);
	egg->lang.nested[CTX] = strdup (s);
	// egg->lang.nestedi[c]++;
	// seems not need to increase egg->lang.nestedi[c]
	/** clear inner levels **/
	for (i = 1; i < 10; i++) {
		// egg->lang.nestedi[context+i] = 0;
		R_FREE (egg->lang.nested[CTX + i]);
	}
}

static void rcc_set_callname(REgg *egg, const char *s) { /* <=== rcc_set_callname */ 
	R_FREE (egg->lang.callname);
	egg->lang.nargs = 0;
	egg->lang.callname = trim (strdup (skipspaces (s)));
	egg->lang.pushargs = !((!strcmp (s, "goto")) || (!strcmp (s, "break")));
}

static char *trim(char *s) { /* <=== trim */ 
	char *o;
	for (o = s; *o; o++) {
		if (is_space (*o)) {
			*o = 0;
		}
	}
	return s;
}

static const char *skipspaces(const char *s) { /* <=== skipspaces */ 
	while (is_space (*s)) {
		s++;
	}
	return s;
}

